pending=[]
for name,item in edits.items():
 p=root/name;raw=p.read_bytes();sha=hashlib.sha256(raw).hexdigest()
 if sha==item['after']:continue
 assert sha==item['before'],'Source changed; review instead of overwrite: '+name
 text=raw.decode('utf-8')
 for old,new in item['replacements']:
  assert text.count(old)==1,(name,old[:80])
  text=text.replace(old,new,1)
 data=text.encode('utf-8');assert hashlib.sha256(data).hexdigest()==item['after'],name
 pending.append((p,data))
for p,data in pending:p.write_bytes(data)
print('Wired',len(pending),'explicit public game files; unrelated applications preserved.')
